"""Self-contained measured trajectories, time cursor and health; no external CDN."""
from support import *
from analyze import rows
import html

def render(out,result):
    data={}
    for name,metrics in result['cases'].items():
        folder=out/name
        if not (folder/'plot_data.json').exists():continue
        plots=read(folder/'plot_data.json')
        for p in plots.values():
            stride=max(1,len(p['t'])//700)
            for key in p:p[key]=p[key][::stride]
        obs=rows(folder/'online/observations.jsonl');ins=rows(folder/'inputs/inputs.jsonl');quality=rows(folder/'icp_gate/quality.jsonl')
        data[name]=dict(paths=plots,metrics=metrics,health=[r for r in obs if r['key']=='health'][::5],quality=quality[::3],residual=[r for r in ins if r.get('key')=='wheel'][::15])
    table=''.join(f'<tr><td>{html.escape(k)}</td><td>{"PASS" if v.get("passed") else "FAIL"}</td><td>{v.get("physical_distance_m",0):.2f}</td><td>{v.get("trajectories",{}).get("fused",{}).get("ate_rmse_m",0):.3f}</td><td>{v.get("rtf",0):.2f}</td><td><a href="{k}/metrics.json">指标</a> · <a href="{k}/runtime.json">命令</a></td></tr>' for k,v in result['cases'].items())
    page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>S05 局部里程计实测</title><style>
body{font:16px system-ui;margin:28px auto;max-width:1280px;background:#f1f5f7;color:#142b38}h1{margin-bottom:6px}section{background:white;padding:20px;margin:18px 0;border-radius:12px}canvas{background:#fff;width:100%;border:1px solid #dde5eb} .grid{display:grid;grid-template-columns:1.25fr 1fr;gap:20px}select,input,button{font:inherit}input{width:48%}table{border-collapse:collapse;width:100%}th,td{text-align:left;padding:8px;border-bottom:1px solid #dae1e7}.muted{color:#596975}.legend span{padding-right:15px}pre{white-space:pre-wrap;font:14px monospace}a{color:#1659ac}@media(max-width:850px){.grid{display:block}}
</style><h1>S05 · 轮速、IMU 与纯激光 ICP</h1><p>STATUS · RUNID · 人工查看：NOT_CHECKED</p>
<section><b>实际 Gazebo 观测；真值仅用于离线评分。</b><p>固定起点对齐，不拟合比例或每段轨迹。局部 odom 保留三维姿态；此处显示 XY 投影。异常诊断触发降速/停止，并不等于在任意农田都能可靠定位。</p><table><tr><th>案例</th><th>结果</th><th>物理路程 m</th><th>融合 ATE m</th><th>RTF</th><th>证据</th></tr>TABLE</table></section>
<section><label>案例 <select id="case"></select></label> <label>仿真时刻 <input id="time" type="range" min="5" step="0.1"><output id="stamp"></output></label><button id="play">播放/暂停</button><p class="legend"><span style="color:#b87611">● 轮速</span><span style="color:#306ab0">● 轮速+IMU</span><span style="color:#00866e">● 多源融合</span><span style="color:#34404a">— 独立真值</span></p><div class="grid"><canvas id="trajectory" width="700" height="550"></canvas><div><canvas id="error" width="570" height="250"></canvas><canvas id="pitch" width="570" height="250"></canvas></div></div><pre id="quality"></pre></section>
<section><h2>健康状态与计算边界</h2><canvas id="health" width="1180" height="100"></canvas><p>绿色 OK；橙色 DEGRADED；红色 STOP。ICP 低几何可观测性/失配先限速 0.2 m/s，持续 2 s 后停止；IMU 超过 0.25 s 未到达直接停止。车端仍执行原 S03 停车反馈门限。</p><p>页面显示的轮速−激光速度差是在线一致性残差，并非 robot_localization 的内部创新。实际 EKF 内部创新与门控计算见 <a href="ekf_internal_trace.txt">有界 C++ 探针</a>；完整 ROS 节点内部调试默认关闭，以控制文件体积。</p><a href="result.json">汇总与门槛</a> · <a href="commands.jsonl">执行命令/退出码</a></section>
<script>const data=DATA;const colors={wheel:'#b87611',wheel_imu:'#306ab0',fused:'#00866e'};const sel=document.getElementById('case'),slider=document.getElementById('time');let current=null;let playing=false;
for(const k of Object.keys(data)){let o=document.createElement('option');o.value=o.textContent=k;sel.append(o);}
function latest(a,t){return a.filter(p=>p.t<=t).slice(-1)[0]||a[0]||{};}
function line(ctx,pts,color){ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.strokeStyle=color;ctx.lineWidth=2;ctx.stroke();}
function chart(id,series,title,t){let cv=document.getElementById(id),c=cv.getContext('2d');c.clearRect(0,0,cv.width,cv.height);let v=series.flatMap(s=>s.y);let lo=Math.min(0,...v),hi=Math.max(.01,...v);let start=5,end=+slider.max;let xp=x=>45+(x-start)/(end-start)*(cv.width-65),yp=y=>cv.height-28-(y-lo)/(hi-lo)*(cv.height-60);c.fillStyle='#243d4a';c.font='15px system-ui';c.fillText(title,12,20);c.fillText(hi.toFixed(2),2,46);c.fillText(lo.toFixed(2),2,cv.height-22);for(const s of series)line(c,s.t.map((x,i)=>[xp(x),yp(s.y[i])]),s.color);line(c,[[xp(t),34],[xp(t),cv.height-25]],'#777');}
function draw(){if(!current)return;let t=+slider.value;document.getElementById('stamp').textContent=t.toFixed(1)+' s';const paths=current.paths,cv=document.getElementById('trajectory'),c=cv.getContext('2d');c.clearRect(0,0,cv.width,cv.height);let all=Object.values(paths).flatMap(p=>p.estimate).concat(paths.fused.truth),xs=all.map(p=>p[0]),ys=all.map(p=>p[1]),minx=Math.min(...xs)-.5,maxx=Math.max(...xs)+.5,miny=Math.min(...ys)-.5,maxy=Math.max(...ys)+.5;let scale=Math.min((cv.width-70)/(maxx-minx),(cv.height-70)/(maxy-miny));let project=p=>[35+(p[0]-minx)*scale,cv.height-35-(p[1]-miny)*scale];c.font='15px system-ui';c.fillStyle='#243d4a';c.fillText('固定起点坐标 · 单位 m · 轨迹截止所选时刻',20,22);line(c,paths.fused.truth.filter((p,i)=>paths.fused.t[i]<=t).map(project),'#34404a');for(const k of Object.keys(colors)){let p=paths[k];if(!p)continue;let pts=p.estimate.filter((v,i)=>p.t[i]<=t).map(project);line(c,pts,colors[k]);if(pts.length){c.beginPath();c.arc(...pts.at(-1),5,0,Math.PI*2);c.fillStyle=colors[k];c.fill();}}
chart('error',Object.keys(colors).filter(k=>paths[k]).map(k=>({t:paths[k].t,y:paths[k].error,color:colors[k]})),'位置误差 m（独立真值评分）',t);chart('pitch',[{t:paths.fused.t,y:paths.fused.rpy.map(r=>r[1]*180/Math.PI),color:colors.fused},{t:paths.fused.t,y:paths.fused.truth_rpy.map(r=>r[1]*180/Math.PI),color:'#34404a'}],'俯仰角 °：融合/真值',t);
let h=latest(current.health,t),q=latest(current.quality,t),r=latest(current.residual,t);document.getElementById('quality').textContent=JSON.stringify({state:h.state,reason:h.reason,max_speed_mps:h.max_speed,icp_valid:q.valid,inlier_ratio:q.inlier_ratio,normal_min_eigenvalue:q.geometry?.normal_eigenvalues?.[0],wheel_minus_lidar_mps:r.innovation_v,wheel_variance:r.variance},null,2);let hc=document.getElementById('health'),hcx=hc.getContext('2d');hcx.clearRect(0,0,hc.width,hc.height);current.health.forEach((h,i)=>{let x=h.t/+slider.max*hc.width,n=current.health[i+1]?.t||h.t+.3;hcx.fillStyle=h.state==='OK'?'#00866e':h.state==='DEGRADED'?'#c38816':'#c6473e';hcx.fillRect(x,15,Math.max(1,(n-h.t)/+slider.max*hc.width),45)});line(hcx,[[t/+slider.max*hc.width,0],[t/+slider.max*hc.width,80]],'#142b38');window.s05Rendered=true;}
function choose(){current=data[sel.value];slider.max=current.paths.fused.t.at(-1);slider.value=slider.max;draw();}sel.addEventListener('change',choose);slider.addEventListener('input',draw);document.getElementById('play').onclick=()=>playing=!playing;setInterval(()=>{if(playing){slider.value=+slider.value>=+slider.max?5:+slider.value+.3;draw();}},100);if(sel.options.length)choose();</script></html>'''
    page=page.replace('STATUS',html.escape(result['status'])).replace('RUNID',html.escape(result['run_id'])).replace('TABLE',table).replace('DATA',json.dumps(data,ensure_ascii=False).replace('</','<\\/'))
    if (out/'comparison.png').exists():page=page.replace('<section><b>', '<p><a href="comparison.png">完整故障序列静态对照图（可导出）</a></p><section><b>',1)
    (out/'index.html').write_text(page)
